  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is multimodal data collection in robotics?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of several synchronized sensor streams during one demonstration, such as RGB, depth, joint states, force-torque, tactile, audio, IMU, and motion capture. Each stream shares a clock and calibration so models can relate what the robot sees to what it feels and does."
        }
      },
      {
        "@type": "Question",
        "name": "Which sensors should we add beyond cameras?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Start from where your policy fails. If failures happen during contact, force-torque and tactile sensing usually help most. Audio helps with click and snap events. Motion capture helps in human demonstration capture. Add one modality at a time and confirm it improves training."
        }
      },
      {
        "@type": "Question",
        "name": "How do you synchronize cameras, force sensors, and tactile data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We use hardware triggering where possible, a shared master clock for networked sensors, and a physical sync tap at the start and end of every session that appears in several streams at once. Measured drift beyond the task tolerance flags the session."
        }
      },
      {
        "@type": "Question",
        "name": "Do VLA models use force or tactile data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Most current VLA models train on images, language, and proprioception. Force and tactile inputs are an active research area. Many teams collect them now, aligned and raw, so the data is ready when their model architecture can use it."
        }
      },
      {
        "@type": "Question",
        "name": "Can you capture egocentric human demonstrations instead of robot data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We run head-mounted and tool-mounted camera rigs with motion capture for human demonstrations, as in our Droyd program. The output includes continuous hand and tool pose aligned with video."
        }
      },
      {
        "@type": "Question",
        "name": "What formats do you deliver multimodal datasets in?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "MCAP, HDF5, Zarr, RLDS, and LeRobot-compatible structures, with raw timestamps per stream, the computed alignment, calibration files, and a sensor manifest for each session."
        }
      }
    ]
  }
